const items = $input.first().json.items || [];
const ids = items.map(i => i.id.videoId).filter(Boolean).join(',');
return [{ json: { video_ids: ids, raw_search: items } }];

const items = $input.first().json.items || [];
const now = Date.now();

const candidates = items.map(v => {
  const publishedAt = new Date(v.snippet.publishedAt).getTime();
  const ageHours = Math.max(1, (now - publishedAt) / (1000 * 60 * 60));
  const views = parseInt(v.statistics.viewCount || '0', 10);
  const likes = parseInt(v.statistics.likeCount || '0', 10);
  const comments = parseInt(v.statistics.commentCount || '0', 10);
  return {
    video_id: v.id,
    title: v.snippet.title,
    channel: v.snippet.channelTitle,
    description: (v.snippet.description || '').slice(0, 300),
    published_at: v.snippet.publishedAt,
    age_hours: Math.round(ageHours),
    views: views,
    likes: likes,
    comments: comments,
    views_per_hour: Math.round(views / ageHours),
    engagement_rate: views > 0 ? +(((likes + comments) / views) * 100).toFixed(2) : 0,
    url: 'https://www.youtube.com/watch?v=' + v.id
  };
});

return [{ json: { candidates } }];

function safeGet(nodeName) { try { const item = $(nodeName).first(); return item ? item.json : null; } catch (e) { return null; } }
const youtubeCandidates = (safeGet('Normalize Candidates') || { candidates: [] }).candidates || [];
const tavilyCandidates = (safeGet('Normalize Tavily Candidates') || { candidates: [] }).candidates || [];
const dna = safeGet('Creator DNA (Demo Profile)') || {};

return [{
  json: {
    creator_dna: dna,
    candidates: [...youtubeCandidates, ...tavilyCandidates]
  }
}];

function safeGet(nodeName) { try { const item = $(nodeName).first(); return item ? item.json : null; } catch (e) { return null; } }
const agentOut = $input.first().json;
const dna = safeGet('Prepare Scoring Input')?.creator_dna || {};
let parsed = { scored_candidates: [] };
try {
  const raw = agentOut.output || agentOut.text || '';
  const cleaned = raw.replace(/```json/g, '').replace(/```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed._parse_error = e.message;
}
const sorted = (parsed.scored_candidates || []).sort((a,b) => (b.overall_score||0) - (a.overall_score||0));
const top = sorted[0] || null;

return [{
  json: {
    creator_dna: dna,
    top_opportunity: top,
    all_scored: sorted
  }
}];

function safeGet(nodeName) { try { const item = $(nodeName).first(); return item ? item.json : null; } catch (e) { return null; } }
const agentOut = $input.first().json;
const prior = safeGet('Pick Top Opportunity') || safeGet('Build Direct Opportunity') || {};
let parsed = {};
try {
  const raw = agentOut.output || agentOut.text || '';
  const cleaned = raw.replace(/```json/g, '').replace(/```/g, '').trim();
  parsed = JSON.parse(cleaned);
