return [{ json: { script: parsed } }];

function safeGet(nodeName) { try { const item = $(nodeName).first(); return item ? item.json : null; } catch (e) { return null; } }
const agentOut = $input.first().json;
const scriptData = safeGet('Parse Script Output') || {};
let parsed = { safe_to_publish: false, fact_check: [], blocking_reasons: ['Fact-check parse failed'] };
try {
  const raw = agentOut.output || agentOut.text || '';
  const cleaned = raw.replace(/```json/g, '').replace(/```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) { parsed._parse_error = e.message; }

const script = scriptData.script || {};
const stockScenes = (script.scenes || []).filter(s => s.visual_type === 'stock' && s.search);
const primarySearch = stockScenes.length > 0 ? stockScenes[0].search : (script.title || 'technology');

return [{ json: { script, fact_check_result: parsed, pexels_query: primarySearch, stock_scene_count: stockScenes.length } }];

function safeGet(nodeName) { try { const item = $(nodeName).first(); return item ? item.json : null; } catch (e) { return null; } }
const pexelsData = $input.first().json;
const prior = safeGet('Parse Fact-Check Output') || {};
const scores = safeGet('Pick Top Opportunity') || safeGet('Build Direct Opportunity') || {};

const script = prior.script || {};
const factCheck = prior.fact_check_result || {};
const broll = (pexelsData.videos || []).map(v => ({
  id: v.id,
  preview_image: v.image,
  duration_seconds: v.duration,
  video_url: (v.video_files && v.video_files[0]) ? v.video_files[0].link : null,
  pexels_url: v.url
}));

return [{
  json: {
    content_package: {
      generated_at: new Date().toISOString(),
      creator_dna: scores.creator_dna || null,
      opportunity: scores.top_opportunity || null,
      script: script,
      fact_check: factCheck,
      broll_assets: broll,
      ready_to_render: !!(factCheck.safe_to_publish && script.title),
      status: factCheck.safe_to_publish ? 'approved_for_production' : 'blocked_pending_review'
    }
  }
}];

function safeGet(nodeName) { try { const item = $(nodeName).first(); return item ? item.json : null; } catch (e) { return null; } }
const dna = safeGet('Creator DNA (Demo Profile)') || {};
const intent = $input.first().json;

return [{
  json: {
    creator_dna: dna,
    top_opportunity: {
      video_id: null,
      title: intent.direct_topic,
      source: 'creator_direct_request',
      momentum: null,
      audience_fit: null,
      novelty: null,
      engagement_quality: null,
      timing: null,
      production_feasibility: null,
      overall_score: 100,
      reasoning: 'Directly requested by the creator - no discovery/scoring needed, this topic is pre-approved.'
    },
    all_scored: []
  }
}];

const pkg = $input.first().json.content_package;
const scenes = (pkg.script && pkg.script.scenes) || [];
const voiceoverText = scenes.map(s => s.voiceover).filter(Boolean).join(' ... ');
return [{ json: { content_package: pkg, voiceover_text: voiceoverText || (pkg.script && pkg.script.hook) || 'No script available.' } }];

const item = $input.first().json;
const pkg = item.content_package;
const audioUrl = item.audio_url;
const scenes = (pkg.script && pkg.script.scenes) || [];
const broll = pkg.broll_assets || [];

const videoClips = scenes.map((scene, i) => {
  const asset = broll.length ? broll[i % broll.length] : null;
  return { asset: { type: 'video', src: asset ? asset.video_url : null, volume: 0 }, start: scene.start, length: Math.max(1, scene.end - scene.start), fit: 'cover' };
}).filter(c => c.asset.src);

const captionClips = scenes.map(scene => ({
  asset: { type: 'title', text: scene.caption || '', style: 'minimal', size: 'small', position: 'bottom' },
  start: scene.start, length: Math.max(1, scene.end - scene.start)
}));

const timeline = { background: '#000000', tracks: [ { clips: captionClips }, { clips: videoClips } ] };
if (audioUrl) { timeline.soundtrack = { src: audioUrl, effect: 'fadeOut' }; }

return [{ json: { content_package: pkg, shotstack_timeline: timeline } }];

const item = $input.first().json;
const renderId = (item.response && item.response.id) || item.id;
const apiKey = $('API Keys Config').first().json.shotstack_api_key;
let videoUrl = null; let finalStatus = 'unknown'; let lastRaw = null;
if (renderId) {
  for (let i = 0; i < 20; i++) {
    const res = await this.helpers.httpRequest({ method: 'GET', url: 'https://api.shotstack.io/edit/stage/render/' + renderId, headers: { 'x-api-key': apiKey }, json: true });
    lastRaw = res;
    const status = res && res.response && res.response.status;
    finalStatus = status;
    if (status === 'done') { videoUrl = res.response.url; break; }
    if (status === 'failed') break;
    await new Promise(r => setTimeout(r, 5000));
  }
}
return [{ json: { final_video_url: videoUrl, render_status: finalStatus, _debug_render_raw: lastRaw } }];

const polled = $input.first().json;
const pkg = $('Build Shotstack Timeline').first().json.content_package;
pkg.final_video_url = polled.final_video_url || null;
pkg.render_status = polled.render_status || 'unknown';
return [{ json: { content_package: pkg } }];

const audioItem = $('ElevenLabs: Generate Voiceover').first();
const uploadInfo = $input.first().json;
const pkg = $('Build Voiceover Script').first().json.content_package;
const audioOk = !!(audioItem && audioItem.binary && audioItem.binary.data);
if (!audioOk) {
  return [{ json: { content_package: pkg, upload: uploadInfo, audio_failed: true, audio_error: audioItem && audioItem.json && audioItem.json.error ? audioItem.json.error.message : 'ElevenLabs did not return audio' } }];
}
return [{ json: { content_package: pkg, upload: uploadInfo, audio_failed: false }, binary: { data: audioItem.binary.data } }];

function safeGet(nodeName) { try { const item = $(nodeName).first(); return item ? item.json : null; } catch (e) { return null; } }
const webhookBody = (safeGet('Generate Content Webhook') || {}).body || {};
if (webhookBody.topic && String(webhookBody.topic).trim()) {
  return [{ json: { mode: 'direct', search_query: String(webhookBody.topic).trim(), direct_topic: String(webhookBody.topic).trim() } }];
}

let parsed = { mode: 'discover', search_query: 'AI tools for beginners', direct_topic: null };
try {
  const agentOut = $input.first().json;
  const raw = agentOut.output || agentOut.text || '';
  const cleaned = raw.replace(/```json/g, '').replace(/```/g, '').trim();
  const p = JSON.parse(cleaned);
  parsed = { mode: p.mode === 'direct' ? 'direct' : 'discover', search_query: p.search_query || parsed.search_query, direct_topic: p.direct_topic || null };
} catch (e) { parsed._parse_error = e.message; }
return [{ json: parsed }];

const item = $input.first();
if (item.json.audio_failed) {
  return [{ json: { content_package: item.json.content_package, shotstack_source_id: null, upload_error: item.json.audio_error } }];
}
const uploadUrl = (item.json.upload && item.json.upload.data && item.json.upload.data.attributes && item.json.upload.data.attributes.url) || (item.json.upload && item.json.upload.url);
const sourceId = (item.json.upload && item.json.upload.data && item.json.upload.data.id) || (item.json.upload && item.json.upload.id);
let uploadError = null;
if (uploadUrl) {
  try {
    const binaryData = await this.helpers.getBinaryDataBuffer(0, 'data');
    const putRes = await fetch(uploadUrl, { method: 'PUT', body: binaryData });
    if (!putRes.ok) { uploadError = 'PUT failed with status ' + putRes.status; }
  } catch (e) { uploadError = e.message; }
} else {
  uploadError = 'no upload url found, raw upload response: ' + JSON.stringify(item.json.upload);
}
return [{ json: { content_package: item.json.content_package, shotstack_source_id: uploadError ? null : sourceId, upload_error: uploadError } }];

const item = $input.first().json;
const sourceId = item.shotstack_source_id;
const apiKey = $('API Keys Config').first().json.shotstack_api_key;
let audioUrl = null; let lastRaw = null; let finalStatus = 'unknown';
if (sourceId) {
  for (let i = 0; i < 10; i++) {
    const res = await this.helpers.httpRequest({ method: 'GET', url: 'https://api.shotstack.io/ingest/stage/sources/' + sourceId, headers: { 'x-api-key': apiKey }, json: true });
    lastRaw = res;
    const attrs = res && res.data && res.data.attributes;
    const status = attrs && attrs.status;
    finalStatus = status;
    if (status === 'ready' || status === 'done') {
      audioUrl = (attrs.outputs && attrs.outputs[0] && attrs.outputs[0].url) || attrs.source || attrs.url || null;
      break;
    }
    if (status === 'failed') break;
    await new Promise(r => setTimeout(r, 3000));
  }
}
return [{ json: { content_package: item.content_package, audio_url: audioUrl, ingest_status: finalStatus, _debug_ingest_raw: lastRaw } }];
